const raw = $json.jobs_block.replace(/\r\n/g, '\n');
const thinkFlag = $json.enable_thinking === 'Thorough (with thinking)';
const blocks = raw.split(/\n*={3,}\n*/).map(b => b.trim()).filter(Boolean);

return blocks.map(block => {
  const lines = block.split('\n');
  const companyLine = lines.find(l => l.toLowerCase().startsWith('company:'));
  const titleLine = lines.find(l => l.toLowerCase().startsWith('job title:') || l.toLowerCase().startsWith('title:'));
  const company_name = companyLine ? companyLine.replace(/company:\s*/i, '').trim() : 'Unknown';
  const job_title = titleLine ? titleLine.replace(/(job )?title:\s*/i, '').trim() : '';
  const job_description = lines.filter(l => !l.toLowerCase().startsWith('company:') && !l.toLowerCase().startsWith('job title:') && !l.toLowerCase().startsWith('title:')).join('\n').trim();
  return { json: { company_name, job_title, job_description, think: thinkFlag } };
});

